'use strict';
const monsterNamesBase=raidNames;raidNames=function(){monsterNamesBase();for(const d of Object.values(JourneyRaid.SPECS).filter(d=>!d.trueBoss)){G.BY[d.boss].name=L(d.en,d.pt);G.BY[d.minion].name=L(d.minionEn,d.minionPt);}if(S?.raid)S.current.name=G.BY[S.raid.bossType||JourneyRaid.TREE].name;};
raidNames();
const monsterConfigBase=trainingConfig;trainingConfig=function(){monsterConfigBase();trainingDraft.raidKind??='tree';const d=JourneyRaid.SPECS[trainingDraft.raidKind]||JourneyRaid.SPECS.tree,entry=document.querySelector('.raid-entry');entry.querySelector('h3').textContent=L('Monster raids','Raids de monstros');entry.querySelector('p').textContent=L('Uses your configured team. Defeat the boss before losing five rounds. No rewards.','Usa sua equipe configurada. Derrote o chefe antes de perder cinco rodadas. Sem recompensas.');entry.insertAdjacentHTML('beforeend',metaButton('raid-kind-open',L(d.en,d.pt)+' ›','','secondary'));};
function monsterPicker(){openModal('<h2>'+L('Choose raid','Escolher raid')+'</h2><div class="stack raid-picker-options">'+Object.entries(JourneyRaid.SPECS).filter(([,d])=>!d.trueBoss).map(([id,d])=>'<button class="offer" data-act="raid-kind-pick" data-id="'+id+'"><img class="monster-choice" src="'+CA[d.boss].sprite+'" alt=""><b>'+L(d.en,d.pt)+'</b></button>').join('')+'</div>');document.querySelector('#overlay>.modal')?.classList.add('raid-picker');}
const monsterGuard=JourneyTraining.guard;JourneyTraining.guard=function(e){if(e.type!=='click')return monsterGuard(e);const el=e.target.closest?.('[data-act]'),a=el?.dataset.act;if(a==='raid-kind-open'||a==='raid-kind-pick'){e.preventDefault();e.stopImmediatePropagation();if(a==='raid-kind-open')monsterPicker();else if(JourneyRaid.SPECS[el.dataset.id]){trainingDraft.raidKind=el.dataset.id;trainingStore();closeModal();trainingConfig();}return true;}
 if(a==='node'&&S?.phase==='map'){const n=S.map.flat().find(n=>n.id===el.dataset.id);if(n?.campaign==='monsters'){e.preventDefault();e.stopImmediatePropagation();const d=JourneyRaid.SPECS[n.raidKind||'tree'];openModal('<div class="eyebrow">'+(n.type==='boss'?actBossLabel(n):'RAID')+'</div><h2>'+L(d.en,d.pt)+'</h2><img class="monster-node-preview" src="'+CA[d.boss].sprite+'" alt=""><p>'+L('Persistent boss health. Five round losses end the run.','Vida persistente do chefe. Cinco rodadas perdidas encerram a run.')+'</p>'+metaButton('enter-node',L('Fight','Combater'),'data-id="'+n.id+'"','primary'));return true;}}
 return monsterGuard(e);};
const monsterSymbolBase=nodeSymbol;nodeSymbol=function(n){return n.campaign==='monsters'?orderMark('monsters'):monsterSymbolBase(n);};
const monsterLegendBase=mapLegend;mapLegend=function(){monsterLegendBase();document.querySelector('.map-legend')?.insertAdjacentHTML('beforeend','<div>'+orderMark('monsters')+'<span>'+L('Monster raid','Raid de monstro')+'</span></div>');document.querySelector('.map-legend')?.insertAdjacentHTML('afterend','<p>'+L('Win both monster raids to face a monster as the map boss.','Vença as duas raids de monstros para enfrentar um monstro como boss do mapa.')+'</p>');};
const monsterMapBase=mapView;mapView=function(){monsterMapBase();const count=S.campaignRoute?.monsterNodes?.length||0;if(count){const target=document.querySelector('.map-toolbar>div');target?.insertAdjacentHTML('beforeend','<small class="route-progress">'+L('Monsters','Monstros')+': '+count+'/2</small>');}};
const monsterResultBase=resultView;resultView=function(){if(!S?.raid?.run)return monsterResultBase();raidNames();const round=S.phase==='roundResult',ended=['victory','defeat'].includes(S.phase),win=S.phase==='victory'||S.phase==='encounterWin';const title=L(round?'The monster survives':win?'Raid won':'Journey ended',round?'O monstro resistiu':win?'Raid vencida':'Fim da jornada');const actions=round?metaButton('next-round',L('Prepare round ','Preparar rodada ')+(S.round+1),'','primary'):ended?metaButton('new',L('Choose another deck','Escolher outro baralho'),'','primary')+metaButton('home',L('Main menu','Menu principal')):metaButton('return-map',L('Continue on map','Seguir pelo mapa'),'','primary');show('<section class="training-result"><div class="eyebrow">RAID</div><h2>'+title+'</h2><div class="bigscore">'+S.score[0]+' : '+S.score[1]+'</div>'+raidHud()+damageReport()+(S.phase==='encounterWin'?'<p>'+L('Gold earned: ','Ouro recebido: ')+G.battleReward(S.mapBattles)+'</p>':'')+(ended?metaResultPanel():'')+'<div class="stack">'+actions+'</div></section>');};
const monsterPaintBase=paintCombat;paintCombat=function(now){monsterPaintBase(now);if(!battle?.raid)return;const r=battle.raid,c=$('combat').getContext('2d'),boss=battle.units.find(u=>u.raidBoss),d=JourneyRaid.spec(r);c.save();if(r.special){const v=r.special;c.strokeStyle=d.color;c.fillStyle=d.color+'35';c.lineWidth=3;c.setLineDash([5,4]);c.beginPath();if(v.rays){for(const a of v.rays){const dx=Math.cos(a),dy=Math.sin(a),n=r.config.spikeWidth,l=r.config.spikeLength;c.moveTo(boss.x-dy*n,boss.y+dx*n);c.lineTo(boss.x+dx*l-dy*n,boss.y+dy*l+dx*n);c.lineTo(boss.x+dx*l+dy*n,boss.y+dy*l-dx*n);c.lineTo(boss.x+dy*n,boss.y-dx*n);c.closePath();}}else if(v.marks){for(const m of v.marks){c.moveTo(m.x+r.config.specialRadius,m.y);c.arc(m.x,m.y,r.config.specialRadius,0,Math.PI*2);}}else if(v.kind==='shock')c.arc(v.x,v.y,r.config.shockRadius,0,Math.PI*2);else{c.moveTo(boss.x,boss.y);c.arc(boss.x,boss.y,600,v.angle-(r.config.breathAngle||r.config.gazeAngle),v.angle+(r.config.breathAngle||r.config.gazeAngle));c.closePath();}c.fill();c.stroke();c.setLineDash([]);}
 for(const h of r.hazards||[]){c.globalAlpha=.3;c.fillStyle=h.color;c.beginPath();c.ellipse(h.x,h.y,h.r,h.r*.55,0,0,Math.PI*2);c.fill();c.globalAlpha=1;}
 if(r.kind==='manticore'){for(const h of r.hunts||[]){const u=battle.units.find(u=>u.uid===h.uid&&u.hp>0);if(!u||h.end<=battle.time)continue;c.strokeStyle=d.color;c.lineWidth=2;c.beginPath();c.arc(u.x,u.y-34,13,0,Math.PI*2);c.moveTo(u.x-18,u.y-34);c.lineTo(u.x+18,u.y-34);c.moveTo(u.x,u.y-52);c.lineTo(u.x,u.y-16);c.stroke();}for(const e of battle.effects.filter(e=>e.kind==='raid-spike')){c.globalAlpha=e.life/e.full;c.strokeStyle=d.color;c.lineWidth=5;c.beginPath();c.moveTo(e.x,e.y);c.lineTo(e.tx,e.ty);c.stroke();c.fillStyle='#fff0c7';c.beginPath();c.arc(e.tx,e.ty,5,0,Math.PI*2);c.fill();}c.globalAlpha=1;}
 if(r.kind==='lich'&&r.channel){c.strokeStyle=d.color;c.lineWidth=3;for(const uid of r.channel.corpses||[]){const u=battle.units.find(u=>u.uid===uid);if(!u)continue;c.beginPath();c.moveTo(boss.x,boss.y-65);c.lineTo(u.x,u.y);c.stroke();c.beginPath();c.ellipse(u.x,u.y,26,12,0,0,Math.PI*2);c.stroke();}}
 if(r.kind==='naga')for(const v of r.venoms||[]){const u=battle.units.find(u=>u.uid===v.uid&&u.hp>0);if(!u)continue;c.fillStyle=d.color;for(let i=0;i<v.stacks;i++){c.beginPath();c.arc(u.x+(i-(v.stacks-1)/2)*9,u.y-48,3,0,Math.PI*2);c.fill();}}
 for(const e of battle.effects.filter(e=>e.kind==='raid-pull')){c.strokeStyle=d.color;c.lineWidth=3;c.globalAlpha=e.life/e.full;c.beginPath();c.moveTo(e.x,e.y);c.lineTo(e.tx,e.ty);c.stroke();}c.globalAlpha=1;
 if(r.kind==='colossus'&&r.broken>0){c.strokeStyle='#b4ffff';c.lineWidth=3;c.beginPath();c.moveTo(boss.x-25,boss.y-100);c.lineTo(boss.x-5,boss.y-75);c.lineTo(boss.x-15,boss.y-54);if(r.broken>=2){c.moveTo(boss.x+25,boss.y-95);c.lineTo(boss.x+5,boss.y-70);c.lineTo(boss.x+18,boss.y-45);}c.stroke();if(r.broken>=2){c.fillStyle='#b7ffff';c.beginPath();c.arc(boss.x,boss.y-73,9+Math.sin(battle.time*6)*2,0,Math.PI*2);c.fill();}}
 if(r.kind==='slime')for(const u of battle.units.filter(u=>u.massSlime&&u.hp>0&&battle.time>=u.returnAt)){c.strokeStyle='#70eaff';c.lineWidth=2;c.setLineDash([3,5]);c.beginPath();c.moveTo(u.x,u.y-20);c.lineTo(boss.x,boss.y-35);c.stroke();c.setLineDash([]);}c.restore();};
